#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -d "$APP" ]] || APP="$ROOT"

INDEX="$APP/index.html"
V26="$APP/ai-nav-layout-v26.js"
V44="$APP/bottom-nav-flush-v44.js"
V51="$APP/native-ai-sheet-v51.js"

for f in "$INDEX" "$V26" "$V44" "$V51"; do
  [[ -f "$f" ]] || { echo "ERROR: missing $f"; exit 1; }
done

DIR="$APP/.memeflow-patches/header-burger-drawer-clean-v1"
mkdir -p "$DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"

INDEX_BAK="$DIR/index.html.$STAMP.bak"
V26_BAK="$DIR/ai-nav-layout-v26.js.$STAMP.bak"
V44_BAK="$DIR/bottom-nav-flush-v44.js.$STAMP.bak"
V51_BAK="$DIR/native-ai-sheet-v51.js.$STAMP.bak"

INDEX_WORK="$DIR/index.html.$STAMP.work.html"
V26_WORK="$DIR/ai-nav-layout-v26.$STAMP.work.js"
V44_WORK="$DIR/bottom-nav-flush-v44.$STAMP.work.js"
V51_WORK="$DIR/native-ai-sheet-v51.$STAMP.work.js"
V26_CANON="$DIR/v26-canonical.$STAMP.js"
V44_CANON="$DIR/v44-canonical.$STAMP.js"
PATCHER="$DIR/patcher.$STAMP.py"
REPORT="$DIR/report.$STAMP.txt"

cp "$INDEX" "$INDEX_BAK"
cp "$V26" "$V26_BAK"
cp "$V44" "$V44_BAK"
cp "$V51" "$V51_BAK"

cp "$INDEX" "$INDEX_WORK"
cp "$V26" "$V26_WORK"
cp "$V44" "$V44_WORK"
cp "$V51" "$V51_WORK"

rollback(){
  cp "$INDEX_BAK" "$INDEX" 2>/dev/null || true
  cp "$V26_BAK" "$V26" 2>/dev/null || true
  cp "$V44_BAK" "$V44" 2>/dev/null || true
  cp "$V51_BAK" "$V51" 2>/dev/null || true
  rm -f "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$V26_CANON" "$V44_CANON" "$PATCHER"
}

trap 'echo "ERROR: HEADER BURGER DRAWER CLEAN V1 failed; restoring exact pre-install files."; rollback' ERR

printf '%s' '' | base64 -d > "$V26_CANON"
printf '%s' '' | base64 -d > "$V44_CANON"
printf '%s' '' | base64 -d > "$PATCHER"

python3 "$PATCHER" "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$V26_CANON" "$V44_CANON" | tee "$REPORT"

node --check "$V26_WORK" >/dev/null
node --check "$V44_WORK" >/dev/null
node --check "$V51_WORK" >/dev/null

grep -q 'MF_HEADER_BURGER_DRAWER_CLEAN_V1' "$V44_WORK"
grep -q 'mf-menu-trigger-v1' "$V44_WORK"
grep -q 'HEADER-MENU-1' "$INDEX_WORK"
! grep -q 'grid-template-columns:repeat(5' "$V44_WORK"
! grep -q 'grid-template-columns:repeat(6' "$V44_WORK"
! grep -q '\.mobile-nav' "$V26_WORK"

cp "$INDEX_WORK" "$INDEX"
cp "$V26_WORK" "$V26"
cp "$V44_WORK" "$V44"
cp "$V51_WORK" "$V51"

cat > "$DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
V26=$V26
V44=$V44
V51=$V51
INDEX_BACKUP=$INDEX_BAK
V26_BACKUP=$V26_BAK
V44_BACKUP=$V44_BAK
V51_BACKUP=$V51_BAK
REPORT=$REPORT
EOF

rm -f "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$V26_CANON" "$V44_CANON" "$PATCHER"
trap - ERR

echo
echo "OK: HEADER BURGER DRAWER CLEAN V1 installed."
echo "Now Stop -> Run, fully close the old Safari tab, then open the app again."
